        let scrollMode: ScrollMode = self.settings.player.scrollMode
        let isVertical: Bool = try Environment.getLayoutEngineFactory(self.settings.display.layoutMode).vertical
        if self._scrollHandlerMode == scrollMode && self._scrollHandlerVertical == isVertical {
