    private func _cursorUpdateBeat(_ lookupResult: MidiTickLookupFindBeatResult, _ stop: Bool, _ shouldScroll: Bool, _ cursorSpeed: Double, _ forceUpdate: Bool = false) throws {
        let beat: Beat = lookupResult.beat
