        let previousBeat: MidiTickLookupFindBeatResult? = self._currentBeat
        let previousCache: BoundsLookup? = self._previousCursorCache
        let previousState: PlayerState? = self._previousStateForCursor
        if !forceUpdate && beat === previousBeat?.beat && cache! === previousCache && previousState! == self._player.state && previousBeat!.start == lookupResult.start {
            return
        }
        let beatBoundings: BeatBounds? = try cache!.findBeat(beat)
        if !TypeHelper.isTruthy(beatBoundings) {
            return
        }
        self._currentBeat = lookupResult
        self._previousCursorCache = cache!
        self._previousStateForCursor = self._player.state
        try self.uiFacade.beginInvoke({ () in
            try self._internalCursorUpdateBeat(lookupResult, stop, cache!, beatBoundings!, shouldScroll, cursorSpeed, forceUpdate)
        })
    }

    /**
