    private func _internalCursorUpdateBeat(_ lookupResult: MidiTickLookupFindBeatResult, _ stop: Bool, _ boundsLookup: BoundsLookup, _ beatBoundings: BeatBounds, _ shouldScroll: Bool, _ cursorSpeed: Double, _ forceUpdate: Bool) throws {
        var paramshouldScroll = try shouldScroll
        let beat: Beat = lookupResult.beat
        let nextBeat: Beat? = lookupResult.nextBeat?.beat
        var duration: Double = lookupResult.duration
        let beatsToHighlight: List<BeatTickLookupItem> = lookupResult.beatLookup.highlightedBeats
        let cursorMode: MidiTickLookupFindBeatResultCursorMode = lookupResult.cursorMode
        let cursorHandler: any ICursorHandler = try self.customCursorHandler ?? jsNonNull(self._defaultCursorHandler)
        let beatCursor: (any IContainer)? = self._beatCursor
        let barCursor: (any IContainer)? = self._barCursor
        let barBoundings: MasterBarBounds = beatBoundings.barBounds.masterBarBounds
        let barBounds: Bounds = barBoundings.visualBounds
        let previousBeatBounds: BeatBounds? = self._currentBeatBounds
        self._currentBeatBounds = beatBoundings
        if TypeHelper.isTruthy(barCursor) {
            cursorHandler.placeBarCursor(barCursor!, beatBoundings)
        }
        let isPlayingUpdate: Bool = self._player.state == PlayerState.Playing && !stop
        var nextBeatX: Double = beatBoundings.realBounds.x + beatBoundings.realBounds.w
        var nextBeatBoundings: BeatBounds? = nil
        if TypeHelper.isTruthy(TypeHelper.isTruthy(nextBeat) && cursorMode == MidiTickLookupFindBeatResultCursorMode.ToNextBext) {
            try nextBeatBoundings = boundsLookup.findBeat(nextBeat!)
            if TypeHelper.isTruthy(TypeHelper.isTruthy(nextBeatBoundings) && nextBeatBoundings!.barBounds.masterBarBounds.staffSystemBounds === barBoundings.staffSystemBounds) {
                nextBeatX = nextBeatBoundings!.onNotesX
            }
        }
        var startBeatX: Double = beatBoundings.onNotesX
        if TypeHelper.isTruthy(beatCursor) {
            let animationWidth: Double = nextBeatX - beatBoundings.onNotesX
            let relativePosition: Double = self._previousTick - lookupResult.start
            var ratioPosition: Double = lookupResult.tickDuration > 0 ? relativePosition / lookupResult.tickDuration : 0.0
            if ratioPosition > 1 {
                ratioPosition = 1.0
            }
            startBeatX = beatBoundings.onNotesX + animationWidth * ratioPosition
            duration -= duration * ratioPosition
            duration = duration / cursorSpeed
            if isPlayingUpdate {
                let jumpCursor: Bool = !TypeHelper.isTruthy(previousBeatBounds) || forceUpdate || self._isInitialBeatCursorUpdate || barBounds.y != previousBeatBounds!.barBounds.masterBarBounds.visualBounds.y || startBeatX < previousBeatBounds!.onNotesX || barBoundings.index > previousBeatBounds!.barBounds.masterBarBounds.index + 1.0 || barBounds.h != previousBeatBounds!.barBounds.masterBarBounds.visualBounds.h
                if jumpCursor {
                    cursorHandler.placeBeatCursor(beatCursor!, beatBoundings, startBeatX)
                }
                try self.uiFacade.beginInvoke({ () in
                    cursorHandler.transitionBeatCursor(beatCursor!, beatBoundings, startBeatX, nextBeatX, duration, cursorMode)
                })
            } else {
                duration = 0.0
                cursorHandler.placeBeatCursor(beatCursor!, beatBoundings, startBeatX)
            }
            self._isInitialBeatCursorUpdate = false
        } else {
            self._isInitialBeatCursorUpdate = true
        }
        self.uiFacade.removeHighlights()
        var shouldNotifyBeatChange: Bool = false
        if isPlayingUpdate {
            if self.settings.player.enableElementHighlighting {
                for highlight in beatsToHighlight {
                    let className: String = BeatContainerGlyph.getGroupId(highlight.beat)
                    try self.uiFacade.highlightElements(className, beat.voice.bar.index)
                }
            }
            paramshouldScroll = !(stop as! Bool)
            shouldNotifyBeatChange = true
        }
        let handler: (any IScrollHandler)? = self.customScrollHandler ?? self._defaultScrollHandler
        if TypeHelper.isTruthy(paramshouldScroll && !self._isBeatMouseDown && TypeHelper.isTruthy(handler)) {
            try handler!.onBeatCursorUpdating(beatBoundings, nextBeatBoundings == nil ? nil : nextBeatBoundings!, cursorMode, startBeatX, nextBeatX, duration)
        }
        if shouldNotifyBeatChange {
            try self._onPlayedBeatChanged(beat)
            try self._onActiveBeatsChanged(ActiveBeatsChangedEventArgs(beatsToHighlight.map({ (i: BeatTickLookupItem) -> Beat in
                return i.beat
            })))
        }
    }

