        try self.uiFacade.triggerEvent(self.container, "beatMouseUp", beat, originalEvent)
    }

    private func _seekToBeat(_ beat: Beat) throws {
        let tickCache: MidiTickLookup? = self._tickCache
        if !TypeHelper.isTruthy(tickCache) {
            return
