        self._currentBeat = nil
        let realStartMasterBarStart: Double = try tickCache!.getMasterBarStart(beat.voice.bar.masterBar)
        let startBeatPlaybackRange: PlaybackRange? = try tickCache!.getRelativeBeatPlaybackRange(beat)
        let startBeatPlaybackStart: Double = startBeatPlaybackRange?.startTick ?? beat.playbackStart
        var beatTick: Double = realStartMasterBarStart + startBeatPlaybackStart
        let playbackRange: PlaybackRange? = self.playbackRange
        if TypeHelper.isTruthy(playbackRange) {
            if beatTick < playbackRange!.startTick {
                beatTick = playbackRange!.startTick
            } else if beatTick > playbackRange!.endTick {
                beatTick = playbackRange!.endTick
            }
        }
        if self._player.state == PlayerState.Paused {
            try self._cursorUpdateTick(beatTick, false, 1.0)
        }
        self.tickPosition = beatTick
    }

