            let endBeat: MidiTickLookupFindBeatResult? = try self._tickCache!.findBeat(jsNonNull(self._trackIndexLookup), range!.endTick)
            if TypeHelper.isTruthy(TypeHelper.isTruthy(startBeat) && TypeHelper.isTruthy(endBeat)) {
                let selectionStart: SelectionInfo = SelectionInfo(beat: startBeat!.beat)
                let selectionEnd: SelectionInfo = SelectionInfo(beat: endBeat!.beat)
                try self._cursorSelectRange(selectionStart, selectionEnd)
            }
        } else {
            try self._cursorSelectRange(nil, nil)
        }
    }

    private func _setupClickHandling() throws {
        try self.canvasElement.mouseDown.on({ (e: any IMouseEventArgs) in
            if !e.isLeftMouseButton {
                return
            }
            if self.settings.player.enablePlaybackRangeSelection || self.settings.player.enableSeekToClick {
                e.preventDefault()
            }
            self._isBeatMouseDown = false
            self._isNoteMouseDown = false
            let relX: Double = try e.getX(self.canvasElement)
            let relY: Double = try e.getY(self.canvasElement)
            let beat: Beat? = self._renderer.boundsLookup?.getBeatAtPos(relX, relY)
            if TypeHelper.isTruthy(beat) {
                try self._onBeatMouseDown(e, beat!)
                if self.settings.core.includeNoteBounds {
                    let note: Note? = try self._renderer.boundsLookup?.getNoteAtPos(beat!, relX, relY)
                    if TypeHelper.isTruthy(note) {
                        try self._onNoteMouseDown(e, note!)
                    }
                }
            }
        })
        try self.canvasElement.mouseMove.on({ (e: any IMouseEventArgs) in
            if !self._isBeatMouseDown {
                return
            }
            let relX: Double = try e.getX(self.canvasElement)
            let relY: Double = try e.getY(self.canvasElement)
            let beat: Beat? = self._renderer.boundsLookup?.getBeatAtPos(relX, relY)
            if TypeHelper.isTruthy(beat) {
                try self._onBeatMouseMove(e, beat!)
                if self._isNoteMouseDown {
                    let note: Note? = try self._renderer.boundsLookup?.getNoteAtPos(beat!, relX, relY)
                    if TypeHelper.isTruthy(note) {
                        try self._onNoteMouseMove(e, note!)
                    }
                }
            }
        })
        try self.canvasElement.mouseUp.on({ (e: any IMouseEventArgs) in
            if !self._isBeatMouseDown {
                return
            }
            if self.settings.player.enablePlaybackRangeSelection || self.settings.player.enableSeekToClick {
                e.preventDefault()
            }
            let relX: Double = try e.getX(self.canvasElement)
            let relY: Double = try e.getY(self.canvasElement)
            let beat: Beat? = self._renderer.boundsLookup?.getBeatAtPos(relX, relY)
            do {
                defer {
                    self._isBeatMouseDown = false
                    self._isNoteMouseDown = false
                }
                try self._onBeatMouseUp(e, beat)
                if self._isNoteMouseDown {
                    if TypeHelper.isTruthy(beat) {
                        let note: Note? = try self._renderer.boundsLookup?.getNoteAtPos(beat!, relX, relY)
                        try self._onNoteMouseUp(e, note)
                    } else {
                        try self._onNoteMouseUp(e, nil)
                    }
                }
            }
        })
    }

