    /**
     * Applies the playback range from the currently highlighted range.
     */
    public func applyPlaybackRangeFromHighlight() throws {
        try self._internalApplyPlaybackRangeFromHighlight()
    }

    private func _internalApplyPlaybackRangeFromHighlight() throws -> Bool {
        if TypeHelper.isTruthy(self._selectionEnd) {
            let startTick: Double = try self._tickCache?.getBeatStart(jsNonNull(self._selectionStart).beat) ?? jsNonNull(self._selectionStart).beat.absolutePlaybackStart
            let endTick: Double = try self._tickCache?.getBeatStart(self._selectionEnd!.beat) ?? self._selectionEnd!.beat.absolutePlaybackStart
            if endTick < startTick {
                let t: SelectionInfo = try jsNonNull(self._selectionStart)
                self._selectionStart = self._selectionEnd!
                self._selectionEnd = t
            }
        } else if !self.settings.player.resetPlaybackRangeOnClick {
            return false
        }
        if TypeHelper.isTruthy(TypeHelper.isTruthy(self._selectionStart) && TypeHelper.isTruthy(self._tickCache)) {
            let tickCache: MidiTickLookup = self._tickCache!
            let realStartMasterBarStart: Double = try tickCache.getMasterBarStart(self._selectionStart!.beat.voice.bar.masterBar)
            let startBeatPlaybackRange: PlaybackRange? = try tickCache.getRelativeBeatPlaybackRange(self._selectionStart!.beat)
            let startBeatPlaybackStart: Double = startBeatPlaybackRange?.startTick ?? self._selectionStart!.beat.playbackStart
            var seekToStart: Bool = self.settings.player.enableSeekToClick
            if TypeHelper.isTruthy(TypeHelper.isTruthy(self._selectionEnd) && self._selectionStart!.beat !== self._selectionEnd!.beat) {
                seekToStart = true
                let realEndMasterBarStart: Double = try tickCache.getMasterBarStart(self._selectionEnd!.beat.voice.bar.masterBar)
                let endBeatPlaybackRange: PlaybackRange? = try tickCache.getRelativeBeatPlaybackRange(self._selectionEnd!.beat)
                let endBeatPlaybackEnd: Double = endBeatPlaybackRange?.endTick ?? self._selectionEnd!.beat.playbackStart + self._selectionEnd!.beat.playbackDuration
                let range: PlaybackRange = PlaybackRange()
                range.startTick = realStartMasterBarStart + startBeatPlaybackStart
                range.endTick = realEndMasterBarStart + endBeatPlaybackEnd - 50.0
                self.playbackRange = range
            } else if self.settings.player.resetPlaybackRangeOnClick {
                self._selectionStart = nil
                self.playbackRange = nil
                try self._cursorSelectRange(self._selectionStart, self._selectionEnd)
            }
            if seekToStart {
                self._currentBeat = nil
                if self._player.state == PlayerState.Paused {
                    try self._cursorUpdateTick(realStartMasterBarStart + startBeatPlaybackStart, false, 1.0)
                }
                self.tickPosition = realStartMasterBarStart + startBeatPlaybackStart
            }
        }
        return true
    }

