        }
        var endX: Double = try jsNonNull(paramendBeat!.bounds).realBounds.x + jsNonNull(paramendBeat!.bounds).realBounds.w
        if paramendBeat!.beat.index == paramendBeat!.beat.voice.beats.length - 1.0 {
