            let staffStartX: Double = try jsNonNull(jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.staffSystemBounds).visualBounds.x
            let staffEndX: Double = try jsNonNull(jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.staffSystemBounds).visualBounds.x + jsNonNull(jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.staffSystemBounds).visualBounds.w
