            startSelection.setBounds(startSelectionBounds.x, startSelectionBounds.y, startSelectionBounds.w, startSelectionBounds.h)
            try jsNonNull(eventArgs.highlightBlocks).push(startSelectionBounds)
            try selectionWrapper!.appendChild(startSelection)
            let staffStartIndex: Double = try jsNonNull(jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.staffSystemBounds).index + 1.0
            let staffEndIndex: Double = try jsNonNull(jsNonNull(paramendBeat!.bounds).barBounds.masterBarBounds.staffSystemBounds).index
            do {
                var staffIndex: Double = staffStartIndex
                while staffIndex < staffEndIndex {
                    let staffBounds: StaffSystemBounds = cache!.staffSystems[(staffIndex).toInt()]
                    let middleSelection: any IContainer = try jsNonNull(self.uiFacade.createSelectionElement())
                    let middleSelectionBounds: Bounds = Bounds(staffStartX, staffBounds.visualBounds.y, staffEndX - staffStartX, staffBounds.visualBounds.h)
                    try jsNonNull(eventArgs.highlightBlocks).push(middleSelectionBounds)
                    middleSelection.setBounds(middleSelectionBounds.x, middleSelectionBounds.y, middleSelectionBounds.w, middleSelectionBounds.h)
                    try selectionWrapper!.appendChild(middleSelection)
                    staffIndex += 1
                }
            }
            let endSelection: any IContainer = try jsNonNull(self.uiFacade.createSelectionElement())
            let endSelectionBounds: Bounds = try Bounds(staffStartX, jsNonNull(paramendBeat!.bounds).barBounds.masterBarBounds.visualBounds.y, endX - staffStartX, jsNonNull(paramendBeat!.bounds).barBounds.masterBarBounds.visualBounds.h)
            try jsNonNull(eventArgs.highlightBlocks).push(endSelectionBounds)
            endSelection.setBounds(endSelectionBounds.x, endSelectionBounds.y, endSelectionBounds.w, endSelectionBounds.h)
            try selectionWrapper!.appendChild(endSelection)
        } else {
            let selection: any IContainer = try jsNonNull(self.uiFacade.createSelectionElement())
            let selectionBounds: Bounds = try Bounds(startX, jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.visualBounds.y, endX - startX, jsNonNull(paramstartBeat!.bounds).barBounds.masterBarBounds.visualBounds.h)
            selection.setBounds(selectionBounds.x, selectionBounds.y, selectionBounds.w, selectionBounds.h)
            try jsNonNull(eventArgs.highlightBlocks).push(selectionBounds)
            try selectionWrapper!.appendChild(selection)
        }
        try (jsCast(self.playbackRangeHighlightChanged, EventEmitterOfT<PlaybackHighlightChangeEventArgs>.self)).trigger(eventArgs)
    }

