        get {
            return self._player.stateChanged
        }
    }

    private func _onPlayerStateChanged(_ e: PlayerStateChangedEventArgs) throws {
        if self._isDestroyed {
            return
        }
        if !e.stopped && e.state == PlayerState.Paused {
            let currentBeat: MidiTickLookupFindBeatResult? = self._currentBeat
            let tickCache: MidiTickLookup? = self._tickCache
            if TypeHelper.isTruthy(TypeHelper.isTruthy(currentBeat) && TypeHelper.isTruthy(tickCache)) {
                try self._player.tickPosition = tickCache!.getBeatStart(currentBeat!.beat)
                try self.scrollToCursor()
            }
        }
        try self.uiFacade.triggerEvent(self.container, "playerStateChanged", e)
    }

