        }
        try self.uiFacade.beginInvoke({ () in
            let cursorSpeed: Double = e.modifiedTempo / e.originalTempo
            try self._cursorUpdateTick(e.currentTick, false, cursorSpeed, false, e.isSeek)
        })
        try self.uiFacade.triggerEvent(self.container, "playerPositionChanged", e)
    }

