    /**
     * Starts the audio export for the currently loaded song.
     */
    public func exportAudio(_ options: AudioExportOptions) async throws -> any IAudioExporter {
        if !TypeHelper.isTruthy(self.score) {
            throw AlphaTabError(AlphaTabErrorType.General, "No song loaded")
        }
        var exporter: any IAudioExporterWorker
        switch self._actualPlayerMode {
        case PlayerMode.EnabledSynthesizer:
            try exporter = self.uiFacade.createWorkerAudioExporter(jsNonNull(self._player.instance))
        default:
            try exporter = self.uiFacade.createWorkerAudioExporter(nil)
        }
        let score: Score = self.score!
        let midiFile: MidiFile = MidiFile()
        let handler: AlphaSynthMidiFileHandler = AlphaSynthMidiFileHandler(midiFile)
        let generator: MidiFileGenerator = MidiFileGenerator(score, self.settings, handler)
        generator.applyTranspositionPitches = false
        try generator.generate()
        let optionsWithChannels: AudioExportOptions = AudioExportOptions()
        optionsWithChannels.soundFonts = options.soundFonts
        optionsWithChannels.sampleRate = options.sampleRate
        optionsWithChannels.useSyncPoints = options.useSyncPoints
        optionsWithChannels.masterVolume = options.masterVolume
        optionsWithChannels.metronomeVolume = options.metronomeVolume
        optionsWithChannels.playbackRange = options.playbackRange
        for (trackIndex, volume) in options.trackVolume {
            if trackIndex < self.score!.tracks.length {
                let track: Track = self.score!.tracks[(trackIndex).toInt()]
                optionsWithChannels.trackVolume.set(track.playbackInfo.primaryChannel, volume)
                optionsWithChannels.trackVolume.set(track.playbackInfo.secondaryChannel, volume)
            }
        }
        for (trackIndex, semitones) in options.trackTranspositionPitches {
            if trackIndex < self.score!.tracks.length {
                let track: Track = self.score!.tracks[(trackIndex).toInt()]
                optionsWithChannels.trackTranspositionPitches.set(track.playbackInfo.primaryChannel, semitones)
                optionsWithChannels.trackTranspositionPitches.set(track.playbackInfo.secondaryChannel, semitones)
            }
        }
        try await exporter.initialize(optionsWithChannels, midiFile, generator.syncPoints, generator.transpositionPitches)
        return exporter
    }
}

/**
 * Holds information about the highlights shown for the playback range.
 */
public final class PlaybackHighlightChangeEventArgs: IRecord {
    /**
     * The beat where the selection starts. undefined if there is no selection.
     */
    public var startBeat: Beat? = nil

    /**
     * The bounds of the start beat to determine its location and size.
     */
    public var startBeatBounds: BeatBounds? = nil

    /**
     * The beat where the selection ends. undefined if there is no selection.
     */
    public var endBeat: Beat? = nil

    /**
     * The bounds of the end beat to determine its location and size.
     */
    public var endBeatBounds: BeatBounds? = nil

    /**
     * A list of the individual rectangular areas where highlight blocks are placed.
     * If a selection spans multiple lines this array will hold all items.
     */
    public var highlightBlocks: List<Bounds>? = nil

    public init(startBeat: Beat? = nil, startBeatBounds: BeatBounds? = nil, endBeat: Beat? = nil, endBeatBounds: BeatBounds? = nil, highlightBlocks: List<Bounds>? = nil) {
        self.startBeat = startBeat
        self.startBeatBounds = startBeatBounds
        self.endBeat = endBeat
        self.endBeatBounds = endBeatBounds
        self.highlightBlocks = highlightBlocks
    }
}

internal final class SelectionInfo: IRecord {
    public var beat: Beat

    public var bounds: BeatBounds? = nil

    public init(beat: Beat, bounds: BeatBounds? = nil) {
        self.beat = beat
        self.bounds = bounds
    }
}

internal final class BoundsLookupVisibilityChecker: IBeatVisibilityChecker {
    public var bounds: BoundsLookup? = nil

    public func isVisible(_ beat: Beat) throws -> Bool {
        let bounds: BoundsLookup? = self.bounds
        if !TypeHelper.isTruthy(bounds) {
            return false
        }
        return try bounds!.findBeat(beat) != nil
    }

    public init() {}
}
